<?php if($allowed['clinical']||$allowed['appointments']||$allowed['treatments']): ?><div class="panel clinic-events" data-reveal><div class="panel-heading"><div><span class="eyebrow">CONTINUIDAD DEL CUIDADO</span><h2>Actividad clínica y agenda</h2><p>Eventos por fecha de registro. Esta sección no suma importes financieros.</p></div><span class="event-count"><?= (int)$events['count'] ?> eventos</span></div><div class="clinical-feed"><?php foreach($events['rows'] as $r): ?><button type="button" class="clinical-event" data-movement="<?= e($r['row_key']) ?>"><span class="event-icon <?= e($r['type']) ?>"><?= icon(['appointment'=>'calendar','clinical'=>'file','odontogram'=>'tooth','treatment'=>'heart'][$r['type']] ?? 'file',22) ?></span><span class="event-copy"><strong><?= e($r['concept']) ?></strong><span><?= e($r['patient']) ?></span><small><?= e($r['author']) ?> · <?= local_date($r['occurred_at']) ?></small></span><span class="badge <?= e($r['status']) ?>"><?= e(App\Services\Dashboard::status($r['status'])) ?></span><?= icon('arrow',17) ?></button><?php endforeach; ?><?php if(!$events['rows']): ?><div class="empty"><h3>Aún no hay actividad para estos filtros.</h3><p>Las citas y actualizaciones aparecerán con paciente, responsable y fecha.</p><a class="text-link" data-dashboard-nav href="<?= e(App\Services\Dashboard::link($f,['event_type'=>'','event_status'=>'','q'=>'','event_page'=>1])) ?>">Limpiar filtros de actividad <?= icon('arrow',15) ?></a></div><?php endif; ?></div><?php view('dashboard/parts/pagination',['f'=>$f,'feed'=>$events,'stream'=>'event']); ?></div><?php endif; ?>
